def components(I):
    H,W=len(I),len(I[0]);seen=set();out=[]
    for r in range(H):
        for c in range(W):
            if (r,c) not in seen:
                col=I[r][c];q=deque([(r,c)]);comp=[(r,c)];seen.add((r,c))
                while q:
                    y,x=q.popleft()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and I[ny][nx]==col:
                            seen.add((ny,nx));comp.append((ny,nx));q.append((ny,nx))
                out.append(comp)
    return out
def denoise(I):
    H,W=len(I),len(I[0])
    comps=components(I)
    res=[[I[r][c] for c in range(W)] for r in range(H)]
    for cm in comps:
        if len(cm)==1:
            r,c=cm[0]
            nb=Counter(I[x][y] for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0) and 0<=r+dr<H and 0<=c+dc<W)
            dom=nb.most_common(1)[0][0]
            res[r][c]=dom
    return res
